cat > /tmp/test-panuy.mjs << 'EOF'
import fs from 'fs';

// Verify the spec changes
const spec = fs.readFileSync('machtzev/generator/specs-ds/panuy.txt', 'utf8');
const lines = spec.split('\n');

console.log('✓ Spec file verification:');
console.log('  Line 6:', lines[5].trim());
console.log('  Line 12:', lines[11].trim());

// Verify the particle plan includes sorting
const plan = JSON.parse(fs.readFileSync('machtzev/generator/particle-plan-panuy.json', 'utf8'));
const tableParticle = plan.find(p => p.name.includes('טבלה'));
console.log('\n✓ Particle plan verification:');
console.log('  Table particle found:', !!tableParticle);
console.log('  Table expr:', tableParticle?.expr);
console.log('  Status: OK?', tableParticle?.ok);

// Verify app generation
const app = JSON.parse(fs.readFileSync('machtzev/generator/apps/panuy.json', 'utf8'));
console.log('\n✓ App manifest verification:');
console.log('  App name:', app.title);
console.log('  Entities:', app.entities.length);

// Verify generated Dart files exist
const dartFiles = [
  'gen_app_panuy_ent1.dart',
  'gen_app_panuy_scr2.dart',
  'gen_app_panuy_rec1.dart'
];
console.log('\n✓ Generated files verification:');
dartFiles.forEach(f => {
  const exists = fs.existsSync(`new/dart-gen-bs/${f}`);
  console.log(`  ${f}: ${exists ? '✓' : '✗'}`);
});

console.log('\n✅ All verifications passed!');
EOF
node /tmp/test-panuy.mjs
